export default "<template>\r\n  <div>\r\n    <raw-loader v-show=\"true\" :mytxt=\"require('!raw-loader!./ModalBase.vue').default\"\r\n      :btnText=\"`Code ModalBase`\"></raw-loader>\r\n\r\n    <b-modal\r\n      ref=\"modal\"\r\n      :title=\"title\"\r\n      :size=\"size\"\r\n      @shown=\"onShown\"\r\n      no-close-on-backdrop\r\n      hide-footer\r\n    >\r\n      <form @submit.stop.prevent=\"onSave\">\r\n        <div  v-for=\"f in listFields\" :key=\"f.key\" class=\"form-group row p-1\">\r\n\r\n          <template v-if=\" f.key==='Id' \">\r\n            <label class=\"col-sm-4 col-form-label font-weight-bold\">Id</label>\r\n            <div class=\"col-sm-8\">\r\n              <input\r\n                autocomplete=\"off\"\r\n                class=\"form-control\"\r\n                readonly\r\n                v-model=\"localSel[f.key]\"\r\n              />\r\n            </div>\r\n          </template>\r\n\r\n          <template v-else-if=\"f.key === '_Ten'\">\r\n            <label class=\"col-sm-4 col-form-label font-weight-bold\">{{f.label}}</label>\r\n            <div class=\"col-sm-8\">\r\n              <input\r\n                autocomplete=\"off\"\r\n                class=\"form-control\"\r\n                v-model=\"localSel[f.key]\"\r\n                :name=\"f.key\"\r\n                v-validate=\"'required'\"\r\n                :class=\"{ 'ko-hop-le': errors.has(f.key) }\"\r\n              />\r\n            </div>\r\n          </template>\r\n\r\n          <template v-else-if=\"f.key === '_Tp'\">\r\n            <label class=\"col-sm-4 col-form-label font-weight-bold\">{{f.label}}</label>\r\n            <div class=\"col-sm-8\">\r\n              <v-select\r\n                v-model=\"localSel[f.key]\"\r\n                v-validate=\"'required'\"\r\n                :name=\"f.key\"\r\n                :reduce=\"(option) => option.id\"\r\n                :options=\"[\r\n                  { label: 'Huế', id: 'HUE' },\r\n                  { label: 'Sài gòn', id: 'SG' },\r\n                  { label: 'Đà nẵng', id: 'DN' },\r\n                  { label: 'Quảng ngãi', id: 'QN' },\r\n                ]\"\r\n                :has-error=\"errors.has(f.key)\"\r\n                :class=\"{ 'is-invalid': errors.has(f.key) }\"                \r\n              />\r\n            </div>\r\n          </template>\r\n\r\n          <template v-else-if=\"f.key === '_MonId'\">\r\n            <label class=\"col-sm-4 col-form-label font-weight-bold\">{{f.label}}</label>\r\n            <div class=\"col-sm-8\">\r\n              <v-select \r\n                v-model=\"localSel[f.key]\" \r\n                v-validate=\"'required'\" \r\n                :name=\"f.key\" \r\n                :reduce=\"(option) => option.id\"\r\n                  :options=\"[\r\n                    { Id:1,Ten: 'Đường' },\r\n                    { Id:2,Ten: 'Sữa' },\r\n                    { Id:3,Ten: 'Bột' },\r\n                  ].map(x=>{\r\n                    return {\r\n                      id:x.Id,\r\n                      label:x.Ten\r\n                    }\r\n                  })\" \r\n                  :has-error=\"errors.has(f.key)\"\r\n                  :class=\"{ 'is-invalid': errors.has(f.key) }\"                \r\n              />\r\n            </div>\r\n          </template>\r\n\r\n          <template v-else-if=\"f.key === '_Loai'\">\r\n            <label class=\"col-sm-4 col-form-label font-weight-bold\">{{f.label}}</label>\r\n            <div class=\"col-sm-8\">\r\n\r\n              <v-select\r\n                multiple\r\n                v-model=\"localSel[f.key]\"\r\n                :name=\"f.key\"\r\n                v-validate=\"'required'\"\r\n                :options=\"['admin', 'user', 'guest']\"\r\n                :has-error=\"errors.has(f.key)\"\r\n                :class=\"{ 'is-invalid': errors.has(f.key) }\"                \r\n              />\r\n\r\n\r\n            </div>\r\n          </template>\r\n\r\n          <template v-else-if=\"f.key === '_Ngay'\">\r\n            <label class=\"col-sm-4 col-form-label font-weight-bold\">{{f.label}}</label>\r\n            <div class=\"col-sm-8\">\r\n              <b-form-datepicker\r\n                v-model=\"localSel[f.key]\"\r\n                :date-format-options=\"{\r\n                  year: 'numeric',\r\n                  month: 'numeric',\r\n                  day: 'numeric',\r\n                }\"\r\n                locale=\"vi\"\r\n                class=\"\"\r\n              >\r\n              </b-form-datepicker>\r\n            </div>\r\n          </template>\r\n\r\n          <template v-else-if=\"f.key === '_Act'\">\r\n            <label class=\"col-sm-4 col-form-label font-weight-bold\">{{f.label}}</label>\r\n            <div class=\"col-sm-8 d-flex align-items-center\">\r\n              <b-form-checkbox \r\n                class=\"my-checkbox\" \r\n                v-model=\"localSel[f.key]\" \r\n                :name=\"f.key\" \r\n                value=true \r\n                unchecked-value=false\r\n              >\r\n              </b-form-checkbox> \r\n            </div>\r\n          </template>\r\n\r\n          <template v-else>\r\n            <label class=\"col-sm-4 col-form-label font-weight-bold\">{{f.label}}</label>\r\n            <div class=\"col-sm-8\">\r\n              <input\r\n                autocomplete=\"off\"\r\n                class=\"form-control\"\r\n                v-model=\"localSel[f.key]\"\r\n                :name=\"f.key\"\r\n                v-validate=\"'required'\"\r\n                :class=\"{ 'ko-hop-le': errors.has(f.key) }\"\r\n              />\r\n            </div>\r\n          </template>\r\n\r\n        </div>\r\n        <!-- <slot /> -->\r\n        <div @click.stop class=\"mb-3\" >\r\n          <slot />\r\n        </div>\r\n        <div class=\"text-right\">\r\n          <button type=\"submit\" class=\"btn btn-primary mr-1\">Save</button>\r\n          <button type=\"button\" class=\"btn btn-secondary\"  @click=\"close\" >Cancel</button>\r\n        </div>\r\n\r\n      </form>\r\n\r\n    </b-modal>\r\n\r\n  </div>\r\n</template>\r\n\r\n<script>\r\n\r\nimport VeeValidate from \"vee-validate\";\r\nimport Vue from \"vue\";\r\nVue.use(VeeValidate, {\r\n  classes: true,\r\n  fieldsBagName: \"veeFields\",\r\n});\r\n\r\nimport moment from \"moment\";\r\nimport vSelect from \"vue-select\";\r\nVue.component(\"v-select\", vSelect);\r\n\r\nexport default {\r\n  name: \"ModalBaseAddEdit\",\r\n  props: {\r\n    value: {\r\n      type: Object,\r\n      default: null,\r\n    },\r\n    title: String,\r\n    size: {\r\n      type: String,\r\n      default: \"md\",\r\n    },\r\n    listFields: {\r\n      type: Array,\r\n      default: () => [],\r\n    },\r\n\r\n\r\n  },\r\n  data() {\r\n    return {\r\n      localSel: {},\r\n    };\r\n  },\r\n  watch: {\r\n    value: {\r\n      immediate: true,\r\n      deep: true,\r\n      handler(val) {\r\n        this.localSel = val ? { ...val } : {};\r\n      },\r\n    },\r\n  },\r\n  methods: {\r\n    onShown(){\r\n      this.$emit('show')\r\n    },\r\n    open() {\r\n      this.$refs.modal.show();\r\n    },\r\n    close() {\r\n      this.$refs.modal.hide();\r\n    },\r\n    async onSave() {\r\n      let result = await this.$validator.validateAll();\r\n      if (!result) {\r\n        alert(`không đủ dữ liệu!`)\r\n        return;\r\n      }\r\n\r\n      this.$emit(\"input\", this.localSel); // 👈 update v-model\r\n      this.$emit(\"save\", this.localSel);  // 👈 callback ngoài\r\n\r\n    },\r\n\r\n  },\r\n};\r\n</script>\r\n\r\n<style>\r\n  .is-invalid .vs__dropdown-toggle {\r\n    border-color: #dc3545;\r\n    box-shadow: 0 0 0 0.2rem rgba(220,53,69,.25);\r\n  }\r\n\r\n</style>\r\n";